CREATE OR REPLACE FUNCTION public.icash_lock_operational_dnc(p_account uuid, p_contact uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.icash_operational_contacts;d public.icash_dnc_verification_receipts;i public.icash_dealmachine_dnc_ingestions;
 oc public.icash_owner_contacts;cost public.icash_cost_observations;o public.icash_operation_spend;reservation public.icash_credit_reservations;policy public.icash_dnc_verification_sources;stamp timestamptz;
begin
 if not public.icash_lock_operational_dnc_before_dm_observations(p_account,p_contact) then return false;end if;
 select * into c from public.icash_operational_contacts where id=p_contact and account_id=p_account;
 select * into d from public.icash_dnc_verification_receipts where id=c.dnc_receipt_id;
 if d.evidence_kind='legacy_record' then return true;end if;
 select * into i from public.icash_dealmachine_dnc_ingestions where screening_id=c.screening_id and account_id=p_account;
 select * into oc from public.icash_owner_contacts where screening_id=c.screening_id and account_id=p_account for share;
 select * into o from public.icash_operation_spend where operation_key=i.operation_key and account_id=p_account for share;
 select * into reservation from public.icash_credit_reservations where id=o.credit_reservation_id for share;
 perform 1 from public.icash_operation_rates where id=o.rate_id for share;
 perform 1 from public.icash_cost_observations where provider='dealmachine'
  and event_key in (i.operation_key,i.operation_key||':people',i.operation_key||':properties',i.operation_key||':deduplicated') order by event_key for share;
 select * into policy from public.icash_dnc_verification_sources where id=d.source_id;
 stamp:=clock_timestamp();
 return coalesce(i.screening_id is not null and oc.screening_id is not null and i.observations>0
  and i.source_id=d.source_id and i.source_hash=c.source_hash and i.source_hash=d.receipt_hash
  and i.source_hash=encode(sha256(convert_to(oc.result::text,'UTF8')),'hex') and i.operation_key=oc.operation_key and i.owner_user_id=c.owner_user_id
  and o.state in ('dispatched','settled') and i.provider_operation_hash=public.icash_dealmachine_operation_hash(o,reservation)
  and exists(select 1 from public.icash_operation_rates where id=o.rate_id and operation='owner_enrichment')
  and i.provider_cost_hash=public.icash_dealmachine_credit_manifest_hash(i.operation_key)
  and public.icash_dealmachine_saved_owner_result_valid(oc.result)
  and i.request_started_at=public.icash_dealmachine_owner_source_started_at(p_account,c.screening_id)
  and d.observation_provenance->>'accountId'=p_account::text and d.observation_provenance->>'screeningId'=c.screening_id::text
  and d.observation_provenance->>'providerOperationHash'=i.provider_operation_hash and d.observation_provenance->>'providerCostHash'=i.provider_cost_hash
  and d.observation_provenance->>'savedResultHash'=i.source_hash and d.observation_provenance->>'operationKey'=i.operation_key
  and d.checked_at=i.request_started_at and d.expires_at=i.original_expires_at and d.observation_recorded_at=i.ingested_at
  and policy.evidence_kind='national_provider_observation' and policy.observation_provider='dealmachine' and policy.observation_scope='national_only'
  and policy.enabled and policy.expires_at>stamp and i.request_started_at+make_interval(secs=>policy.max_observation_age_seconds)>stamp,false);
end $function$

CREATE OR REPLACE FUNCTION public.icash_dealmachine_observation_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_table_name='icash_owner_contacts' then
  if (exists(select 1 from public.icash_dealmachine_dnc_ingestions where screening_id=old.screening_id)
   or exists(select 1 from public.icash_dealmachine_dnc_rejections where screening_id=old.screening_id))
   and (tg_op='DELETE' or to_jsonb(new) is distinct from to_jsonb(old)) then raise exception 'Ingested owner-source binding is immutable';end if;
 elsif old.evidence_kind='national_provider_observation' then
  if tg_op='DELETE' or to_jsonb(new)-'revoked_at' is distinct from to_jsonb(old)-'revoked_at'
   or (old.revoked_at is not null and new.revoked_at is distinct from old.revoked_at) then raise exception 'Derived DNC observation is immutable';end if;
 end if;
 if tg_op='DELETE' then return old;end if;return new;
end $function$

CREATE OR REPLACE FUNCTION icash_research_private.take_reserved_request(p_kind text, p_account uuid, p_operation text, p_request uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.icash_dealmachine_request_budget;s jsonb;allowed boolean:=false;protected boolean:=false;
 stamp timestamptz;first_funded timestamptz;
begin
 if p_request is not null and (p_kind is null or p_kind not in ('search_estimate','property_search','owner_preview','owner_lookup','exclusion_create','exclusion_sync','geography','buyer_estimate','buyer_search','property_lookup','photo')
  or length(coalesce(p_operation,''))>200) then return false;end if;
 select * into b from public.icash_dealmachine_request_budget where id=1 for update;
 if not found then return false;end if;
 if p_request is not null and (exists(select 1 from icash_research_private.requests where id=p_request)
  or exists(select 1 from icash_research_private.request_reserve_admissions where request_id=p_request)) then return false;end if;
 -- Recheck time after waiting on the limiter, so a stale transaction cannot
 -- extend the new account's first 24 hours or the provider's rolling window.
 stamp:=clock_timestamp();
 s:=icash_research_private.request_reserve_state(stamp);
 if s is not null and public.icash_dealmachine_provider_available()
  and b.minute_start<=stamp and b.minute_used>=0 and b.minute_limit>0 then
  if b.minute_start<=stamp-interval '1 minute' then b.minute_start:=stamp;b.minute_used:=0;end if;
  if b.day_start<=stamp-interval '24 hours' then b.day_start:=stamp;b.day_used:=0;end if;
  if b.minute_used<b.minute_limit and b.day_used<b.day_limit then
   allowed:=(s->>'ordinaryRemaining')::integer>0;
   if not allowed and p_request is not null and p_operation is not null and length(p_operation)>0
    and (p_kind in ('search_estimate','property_search','owner_preview','owner_lookup','geography','property_lookup')
    or (p_kind='exclusion_sync' and icash_research_private.starter_exclusion_request_allowed(p_account,p_operation,stamp)))
    and (s->>'reserveRemaining')::integer>0
    and icash_research_private.starter_request_allowance(p_account,stamp)>0 then
    allowed:=true;protected:=true;
   end if;
  end if;
 end if;
 if p_request is not null then
  insert into icash_research_private.requests(id,kind,account_id,operation_key,admitted,result)
   values(p_request,p_kind,p_account,p_operation,allowed,case when allowed then null else '{"outcome":"quota_wait"}'::jsonb end);
 end if;
 if not allowed then return false;end if;
 if protected then
  select credited_at into first_funded from public.icash_funding_orders
   where account_id=p_account and mode='live' and state='paid' and credited_at is not null order by credited_at limit 1;
  insert into icash_research_private.request_reserve_admissions(request_id,account_id,day_start,first_funded_at,created_at)
   values(p_request,p_account,b.day_start,first_funded,stamp);
 end if;
 update public.icash_dealmachine_request_budget set minute_start=b.minute_start,minute_used=b.minute_used+1,
  day_start=b.day_start,day_used=b.day_used+1 where id=1;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_reserve_before_fractional(p_account uuid, p_operation text, p_rate uuid, p_permission_until timestamp with time zone, p_financial_checked_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_financial_eligible boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare b public.icash_operating_budget; r public.icash_operation_rates; o public.icash_operation_spend; cat text; n numeric; total numeric:=0; held bigint; daily numeric; cr uuid; required numeric; price numeric; dm_mult numeric; data_unit bigint; data_basis text;
begin
 if p_operation is null or length(p_operation) not between 1 and 160 then raise exception 'Invalid operation'; end if;
 select * into b from public.icash_operating_budget where id=1 for update;
 if not b.enabled then raise exception 'Automation on hold'; end if;
 select * into o from public.icash_operation_spend where operation_key=p_operation;
 if found then
  if o.account_id<>p_account or o.rate_id<>p_rate then raise exception 'Operation conflict'; end if;
  return jsonb_build_object('operationKey',o.operation_key,'state',o.state,'reservedMicros',o.reserved_micros);
 end if;
 select * into r from public.icash_operation_rates where id=p_rate for share;
 if not found or not r.enabled or r.verified_at>now() or r.expires_at<=now() then raise exception 'Verified rate required'; end if;
 if public.icash_voice_credit_bound(p_account,p_operation,p_rate) is not null then
  r.charge_cents:=(public.icash_voice_credit_bound(p_account,p_operation,p_rate)->>'charge_cents')::bigint;
  r.costs_micros:=public.icash_voice_credit_bound(p_account,p_operation,p_rate)->'costs_micros';
 end if;
 if public.icash_reception_credit_bound(p_account,p_operation,p_rate) is not null then
  r.charge_cents:=(public.icash_reception_credit_bound(p_account,p_operation,p_rate)->>'charge_cents')::bigint;
  r.costs_micros:=public.icash_reception_credit_bound(p_account,p_operation,p_rate)->'costs_micros';
 end if;
 if p_permission_until is null or p_permission_until<=now() then raise exception 'Permission expired'; end if;
 if r.operation='seller_call' and not public.icash_limited_seller_voice(p_account,p_operation) and not public.icash_cancellation_voice_current(p_account,p_operation) and not exists(select 1 from public.icash_voice_jobs meta_job where meta_job.account_id=p_account and 'voice:'||meta_job.id=p_operation and public.icash_meta_voice_context(p_account,meta_job.id) is not null) and (p_financial_eligible is distinct from true or p_financial_checked_at is null or p_financial_checked_at>now() or p_financial_checked_at<now()-interval '24 hours') then raise exception 'Financial screening required'; end if;
 foreach cat in array array['dealmachine','elevenlabs','twilio','messaging','email','llm','vercel','railway','supabase','github','payments','title_and_signing','support_and_overhead','acquisition','refund_and_dispute_reserve','other'] loop
  if jsonb_typeof(r.costs_micros->cat) is distinct from 'number' then raise exception 'Unknown cost: %',cat; end if;
  n:=(r.costs_micros->>cat)::numeric;
  if n<0 or n<>trunc(n) or n>9007199254740991 then raise exception 'Invalid cost'; end if;
  total:=total+n;
 end loop;
 if public.icash_vip_active(p_account) then b.standard_cost_multiplier:=b.standard_cost_multiplier*0.7;b.elevenlabs_cost_multiplier:=b.elevenlabs_cost_multiplier*0.7;end if;
 if r.operation='seller_lead' then
  b.standard_cost_multiplier:=public.icash_seller_lead_rate_multiplier(p_account,p_operation,p_rate)*case when public.icash_vip_active(p_account) then 0.7 else 1 end;
  b.elevenlabs_cost_multiplier:=b.standard_cost_multiplier;
 end if;
 if r.operation in ('property_search','owner_enrichment','buyer_discovery') then
  dm_mult:=3*case when public.icash_vip_active(p_account) then 0.7 else 1 end;
  select credit_micros,cost_basis into strict data_unit,data_basis from public.icash_data_cost_settings where provider='dealmachine';
 end if;
 -- Match JS: round reserve up to a cent after adding buffer.
 held:=ceil(total*(10000+r.buffer_bps)/10000);
 required:=ceil((total*b.standard_cost_multiplier-(r.costs_micros->>'elevenlabs')::numeric*(b.standard_cost_multiplier-b.elevenlabs_cost_multiplier)+coalesce((r.costs_micros->>'dealmachine')::numeric*(dm_mult-b.standard_cost_multiplier),0))*(10000+r.buffer_bps)/10000);
 price:=r.charge_cents::numeric*10000;
 if r.operation='sms_send' then
 select customer_price_micros into price from public.icash_text_messages where 'text:'||id=p_operation and account_id=p_account;
 end if;

 if r.flat_customer_price_cents is not null then
  if r.operation<>'sms_send' or price is distinct from r.flat_customer_price_cents::numeric*10000 then raise exception 'SMS flat price snapshot mismatch';end if;
  -- Snapshot cost-coverage accounting only for this explicit flat-price operation.
  -- The existing fractional ledger charges the immutable customer_price_micros.
  required:=held;b.standard_cost_multiplier:=1;b.elevenlabs_cost_multiplier:=1;
 end if;
 if price is null or price<required then raise exception 'Price below provider cost multiplier';end if;
 if b.require_company_reserve and b.funded_micros::numeric-b.spent_micros-b.reserved_micros-b.protected_micros<held then raise exception 'Company budget exhausted'; end if;
 select coalesce(sum(actual_micros),0) into daily from public.icash_operation_spend where settled_at>now()-interval '24 hours';
 if b.require_company_reserve and daily+b.reserved_micros+held>b.daily_limit_micros then raise exception 'Company daily limit'; end if;
 cr:=public.icash_reserve_credit(p_account,p_operation,r.charge_cents);
 insert into public.icash_operation_spend(operation_key,account_id,rate_id,credit_reservation_id,charge_cap_cents,reserved_micros,permission_until,financial_checked_at)
 values(p_operation,p_account,p_rate,cr,r.charge_cents,held,p_permission_until,p_financial_checked_at);
 update public.icash_operation_spend set standard_cost_multiplier=b.standard_cost_multiplier,elevenlabs_cost_multiplier=b.elevenlabs_cost_multiplier,required_revenue_micros=required,dealmachine_cost_multiplier=dm_mult,data_unit_cost_micros=data_unit,data_cost_basis=data_basis where operation_key=p_operation;
 update public.icash_operating_budget set reserved_micros=reserved_micros+held where id=1;
 return jsonb_build_object('operationKey',p_operation,'state','reserved','reservedMicros',held);
end $function$

CREATE OR REPLACE FUNCTION public.icash_guard_prospecting_spend()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare kind text;required bigint;
begin
 if not public.icash_new_prospect_operation(new.account_id,new.operation_key,new.rate_id) then return new;end if;
 perform 1 from public.icash_operating_budget where id=1 for update;
 select operation into kind from public.icash_operation_rates where id=new.rate_id;
 required:=new.charge_cap_cents;
 if kind in ('property_search','owner_enrichment') then
  required:=public.icash_research_admission_quote(new.account_id,kind,required);
  if public.icash_research_waiting_on_outreach(new.account_id) then
   raise exception 'Prospecting budget reached' using detail=jsonb_build_object('quoteCents',required)::text;
  end if;
 elsif kind in ('sms_send','mms_send') and public.icash_research_waiting_on_outreach(new.account_id) then
  required:=required+public.icash_prospecting_outreach_floor(new.account_id);
 end if;
 if public.icash_prospecting_available(new.account_id)<required then
  raise exception 'Prospecting budget reached' using detail=jsonb_build_object('quoteCents',required)::text;
 end if;
 select id into new.prospecting_budget_id from public.icash_prospecting_budgets where account_id=new.account_id order by id desc limit 1;
 if new.prospecting_budget_id is null then raise exception 'Prospecting budget reached' using detail=jsonb_build_object('quoteCents',required)::text;end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.icash_settle_estimated_operation(p_operation text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare j public.icash_text_ai_jobs;
begin
 select jobs.* into j from public.icash_text_ai_jobs jobs join public.icash_operation_spend o on o.operation_key='sms-ai:'||jobs.id and o.account_id=jobs.account_id join public.icash_operation_rates r on r.id=o.rate_id and r.version in ('sms-ai-gpt41mini-tokens-20261007','sms-ai-gpt41mini-tokens-20261007:standing-delivery-20261014') where o.operation_key=p_operation;
 if found then return public.icash_settle_sms_ai_tokens(j.account_id,j.id);end if;
 return public.icash_settle_estimate_before_sms_tokens(p_operation);
end $function$
